import org.junit.jupiter.api.Test;

class PackedHashJoinBindingMaskTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void packedPossibleAndAssuredMasksMatchRuntimeSchemasAcrossBindingOperators() {
		StatementPattern stream = pattern("entity", "value");
		Projection projection = new Projection(stream.clone(),
				new ProjectionElemList(new ProjectionElem("value", "projectedValue")));
		Extension extension = new Extension(stream.clone(), new ExtensionElem(new Var("value"), "derived"));
		Group group = new Group(stream.clone(), List.of("entity"),
				List.of(new GroupElem("count", new Count(new ValueConstant(VF.createLiteral("x"))))));
		BindingSetAssignment assignments = assignments();
		List<TupleExpr> expressions = List.of(
				stream,
				new Union(pattern("shared", "leftOnly"), pattern("shared", "rightOnly")),
				new LeftJoin(pattern("shared", "leftOnly"), pattern("shared", "nullable")),
				projection,
				extension,
				group,
				assignments,
				new Join(new LeftJoin(pattern("key", "required"), pattern("key", "optional")),
						new Join(assignments.clone(), extension.clone())));

		for (TupleExpr expression : expressions) {
			assertPackedSchemaParity(expression);
		}
	}

	@Test
	void packedHashMasksMatchRuntimeLookupAndCompatibilityContract() {
		LeftJoin left = new LeftJoin(pattern("key", "leftOnly"), pattern("key", "nullable"));
		LeftJoin right = new LeftJoin(pattern("key", "rightOnly"), pattern("key", "nullable"));
		PackedQuery query = PackedQueryCodec.encodeForPlanning(new Join(left, right));
		int joinId = query.rootRelId();
		int leftId = query.relChild(joinId, 0);
		int rightId = query.relChild(joinId, 1);
		int lookupMaskId = query.intersectMasks(query.relAssuredMaskId(leftId), query.relAssuredMaskId(rightId));
		int compatibilityMaskId = query.intersectMasks(query.relOutputMaskId(leftId), query.relOutputMaskId(rightId));

		assertThat(query.bindingNames(lookupMaskId)).containsExactly("key");
		assertThat(query.bindingNames(compatibilityMaskId)).containsExactly("key", "nullable");
	}

	private static void assertPackedSchemaParity(TupleExpr expression) {
		PackedQuery query = PackedQueryCodec.encodeForPlanning(expression);
		StreamBindingSchema schema = StreamBindingSchema.from(expression);

		assertThat(Set.copyOf(query.bindingNames(query.relOutputMaskId(query.rootRelId()))))
				.as("possible bindings for %s", expression.getClass().getSimpleName())
				.isEqualTo(schema.possible());
		assertThat(Set.copyOf(query.bindingNames(query.relAssuredMaskId(query.rootRelId()))))
				.as("assured bindings for %s", expression.getClass().getSimpleName())
				.isEqualTo(schema.assured());
	}

	private static BindingSetAssignment assignments() {
		QueryBindingSet complete = new QueryBindingSet();
		complete.addBinding("key", VF.createIRI("urn:key:1"));
		complete.addBinding("nullable", VF.createLiteral("present"));
		QueryBindingSet partial = new QueryBindingSet();
		partial.addBinding("key", VF.createIRI("urn:key:2"));
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setBindingNames(Set.of("key", "nullable"));
		assignment.setBindingSets(List.of(complete, partial));
		return assignment;
	}

	private static StatementPattern pattern(String subject, String object) {
		return new StatementPattern(new Var(subject),
				Var.of("_const_predicate", VF.createIRI("urn:predicate"), false, true),
				new Var(object));
	}
}
